package com.aoo.bcg.gamespi.api;
import static org.junit.jupiter.api.Assertions.*;import org.junit.jupiter.api.Test;
class ApiSurfaceRegistryTest{@Test void rejectsShadowHandlerForSameHttpOrWssEntry(){var registry=new ApiSurfaceRegistry(ApiOwnershipCatalog.standard(),ApiLifecycleCatalog.standard());registry.bind(new ApiSurfaceRegistry.Binding(ApiOwnershipCatalog.Transport.HTTP,"/api/v2/admin/game-profiles","GameProfilesHandler"));assertThrows(IllegalStateException.class,()->registry.bind(new ApiSurfaceRegistry.Binding(ApiOwnershipCatalog.Transport.HTTP,"/api/v2/admin/game-profiles","ShadowHandler")));registry.bind(new ApiSurfaceRegistry.Binding(ApiOwnershipCatalog.Transport.WSS,"common.room.join_req","JoinHandler"));assertThrows(IllegalStateException.class,()->registry.bind(new ApiSurfaceRegistry.Binding(ApiOwnershipCatalog.Transport.WSS,"common.room.join_req","OtherJoinHandler")));}}
